using System;using System.IO;using System.Linq;using System.Threading.Tasks;using System.Reflection;using System.Web.Script.Serialization;using SplifyWin;
class Upgrade111To11220261023 {
 static int count;static void Check(bool yes,string text){if(!yes)throw new Exception(text);Console.WriteLine("PASS "+(++count)+" "+text);}
 static int Main(string[] a){try{string root=Path.GetFullPath(a[0]),metadata=Path.GetFullPath(a[1]),mode=a[2];Directory.CreateDirectory(root);Check(typeof(NetworkCore).Assembly.GetName().Version.ToString(3)=="1.1.1","test executes installed 1.1.1 update implementation");RuntimeResources.Prepare(root);var core=new NetworkCore(new StateStore(root));var manifest=RuntimeResources.Read(new StreamReader(typeof(NetworkCore).Assembly.GetManifestResourceStream("Mcrf.Runtime.Resources.json")).ReadToEnd());var original=manifest.Resources.Select(r=>r.Hash).ToArray();if(mode=="local"){File.Copy(a[3],core.CurlExecutable,true);Environment.SetEnvironmentVariable("MCRF_TEST_BUNDLE",Path.GetFullPath(a[4]));Environment.SetEnvironmentVariable("MCRF_TEST_COMPONENT_DIR",Path.Combine(Path.GetDirectoryName(Path.GetFullPath(a[4])),"runtime-components"));Environment.SetEnvironmentVariable("MCRF_TEST_TRANSFER_LOG",Path.Combine(root,"transfers.log"));}
 using(var updates=new AppUpdates(core,url=>Task.FromResult(url.Contains("vnenapravo7-source/mcrf/releases")?File.ReadAllText(metadata):"[]"))){var state=new ClientState();updates.Check(state).GetAwaiter().GetResult();var row=updates.Items.Single(x=>x.Id=="app");Check(row.Available&&AppUpdates.CompareVersion(row.Version,"1.1.2")==0,"1.1.1 discovers 1.1.2 as available");Check(row.Asset.name=="mcrf-app-update.zip"&&row.Asset.size<3000000,"installed updater selects small ZIP, not full EXE");updates.Apply(row,state,new StateStore(root)).GetAwaiter().GetResult();Check(File.Exists(row.AppliedVersion),"installed updater stages new executable");var module=AppRuntime.ReadModule(File.ReadAllText(Path.Combine(Path.GetDirectoryName(row.AppliedVersion),"module.json")));Check(module.Version=="1.1.2"&&AssemblyName.GetAssemblyName(row.AppliedVersion).Version.ToString(3)=="1.1.2","staged module and assembly versions match release");Check(module.Runtime.Resources.All(r=>RuntimeResources.Present(root,r)),"all runtime dependency size and SHA checks pass");var changed=module.Runtime.Resources.Where(r=>!original.Contains(r.Hash)).ToArray();Check(changed.Length==1&&changed[0].Name.Contains("sing-box"),"only changed runtime component is network core");if(mode=="local"){var transfers=File.ReadAllLines(Path.Combine(root,"transfers.log"));Check(transfers.Length==2&&transfers[0].EndsWith("mcrf-app-update.zip")&&transfers[1].EndsWith("runtime-"+changed[0].Hash+".bin"),"downloads only app ZIP and changed core; unchanged components reused");}AppRuntime.Activate(root,module);Check(File.Exists(Path.Combine(root,"runtime","active-app.json")),"normal verified activation pointer created in isolated profile");Console.WriteLine("VERIFIED "+mode+" update bytes="+(row.Asset.size+changed.Sum(r=>r.Size)));}return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
